/* selectMasterMdCtBuyerJoinAlterRequestApprovalChargeEntryUserIdCheck */
SELECT
	COUNT(KEP_USER_ID) CNT
FROM MIS_BUYER_MNG
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND KEP_USER_ID			= #{KEP_USER_ID}
AND KEP_DEPT				= #{KEP_DEPT}
AND POSITION_GROUP	= #{POSITION_GROUP}
AND ITEM_GROUP			= #{ITEM_GROUP}
AND STATUS					= 'C'

