/*updateMasterMdCtBuyerJoinAlterRequestApprovalPop*/ UPDATE ICOMCMPY SET COM_NAME_LOC = #{st_com_name_loc}, /* 회사명(국문) */ COM_NAME_ENG = #{st_com_name_eng}, /* 회사명(영문) */ ESTABLISH_DATE = #{st_establish_date}, /* 설립년도 */ CEO_NAME_LOC = #{st_ceo_name_loc}, /* 대표자(국문) */ CEO_NAME_ENG = #{st_ceo_name_eng}, /* 대표자(영문) */ TEL_NO = #{st_tel_no}, /* 대표자전화번호 */ FAX_NO = #{st_fax_no}, /* 대표자FAX번호 */ INDUSTRY_TYPE = #{st_industry_type}, /* 업태 */ BUSINESS_ITEMS = #{st_business_items}, /* 종목 */ ZIP_CODE = #{st_zip_code}, /* 우편번호 */ MAIL_SEND_FLAG = #{st_mail_send_flag}, /* 메일링서비스 */ ADDRESS_LOC = #{st_address_loc}, /* 주소(국문) */ ADDRESS_ENG = #{st_address_eng}, /* 주소(영문) */ ZIP_KEY = #{st_zip_key}, /* 도로명주소 키 */ ADDRESS_LOC1 = #{st_address}, /* 도로명주소 */ ADDRESS_LOC2 = #{st_address_dt}, /* 도로명주소 상세주소 */ HP_ADDRESS = #{st_hp_address}, /* 홈페이지주소 */ CORP_REG_NO = #{st_corp_reg_no}, /* 법인등록번호 */ TRADE_REG_NO = #{st_trade_reg_no}, /* 무역업등록번호 */ DUNS_NO = #{st_duns_no}, /* DUNS-NO */ GR_EMP_NM = #{st_gr_emp_nm}, /* 입고담당자명 */ GR_EMP_TEL = #{st_gr_emp_tel}, /* 입고담당자연락처 */ AC_EMP_NM = #{st_ac_emp_nm}, /* 경리담당자명 */ AC_EMP_TEL = #{st_ac_emp_tel}, /* 경리담당자연락처 */ PAY_RECVER = #{st_pay_recver}, /* 물품대금 수령처 */ CONTRACT_EXPIRE_DATE = #{st_contract_expire_date}, /* 계약만료일 */ CONTRACT_AUTO_RENEW = #{st_contract_auto_renew}, /* 자동연장여부 */ KEP_BUSINESS_ITEM = #{st_kep_business_item}, /* 회원사업종코드 */ CAR_DELIV_CNT = #{st_car_deliv_cnt}, /* 차량일배송횟수 */ IMAGE_KEY = #{st_image_key}, /* 첨부파일 */ INCOME_PRICE_OPEN_FLAG = 'N', /* 매입단가오픈여부 */ DUEDATE_FLAG = #{st_duedate_flag}, /* 납기일구분 */ CORP_CODE = #{st_corp_code}, /* 법인그룹코드 */ SMS_RECV_FLAG = #{st_sms_recv_flag}, /* SMS수신여부 */ AGENT_OPEN_FLAG = #{st_agent_open_flag}, /* 협력사공개여부 */ BUDGET_FLAG = #{st_budget_flag}, /* 예산관리여부 */ LOGO_YN = #{st_logo_yn}, /* 로고사용여부 */ DS_FLAG = 'N', /* 납품수량변경유무(납기관리개선으로 N으로 고정) */ WAREHOUSE_CODE = #{st_warehouse_code}, REMARK = #{st_remark}, /* 비고 */ DELY_AREA = #{st_cmpy_dely_area}, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), /* 수정일자 */ CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'), /* 수정시간 */
RE_NOTE = #{st_re_note},
PROCESS_TYPE = #{st_process_type}
, CHANGE_USER_ID = #{st_user_id} /* 수정자 아이디 */
WHERE COM_CODE = #{com_code}


UPDATE ACNTBUYR
SET
	PAY_TERMS	= #{st_pay_terms},
	PAY_TYPE		= #{st_pay_type}
WHERE BUYER	= #{com_code}


/* updateMasterMdCtBuyerJoinAlterRequestApprovalChargeEntryList */
UPDATE MIS_BUYER_MNG
SET PRIORITY				= DECODE(#{PRIORITY}, '1', 'Y', '')
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND KEP_DEPT				= #{KEP_DEPT}
AND KEP_USER_ID			= #{KEP_USER_ID}
AND POSITION_GROUP	= #{POSITION_GROUP}
AND ITEM_GROUP			= #{ITEM_GROUP}


/* deletetMasterMdCtBuyerChargeEntryList */
UPDATE MIS_BUYER_MNG
SET STATUS					= 'O'
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND KEP_DEPT				= #{KEP_DEPT}
AND KEP_USER_ID			= #{KEP_USER_ID}
AND POSITION_GROUP	= #{POSITION_GROUP}
AND ITEM_GROUP			= #{ITEM_GROUP}


/* updateMasterMdCtCod3SgMarginList */
UPDATE ICOMCOD3 COD
SET FLAG = 'Y'
, TEXT1 = #{MARGIN} 
WHERE COD.BUYER ='KRKORE0001'
AND COD.TYPE ='CMSG'
AND COD.CODE1 = #{com_code}
AND COD.CODE2 = #{SG_ID}


/* insertMasterMdCtCod3SgMarginList */
INSERT INTO ICOMCOD3
(
  BUYER
  , TYPE
  , CODE1
  , CODE2
  , TEXT1
  , FLAG
  , ADD_USER_ID
  , ADD_DATE
)VALUES(
  'KRKORE0001'
  , 'CMSG'
  , #{com_code}
  , #{SG_ID}
  , #{MARGIN}
  , 'Y'
  , #{st_user_id}
  , TO_CHAR(SYSDATE, 'YYYYMMDD')
)
